import {
  Column,
  CreateDateColumn,
  Entity,
  OneToMany,
  PrimaryGeneratedColumn,
  UpdateDateColumn,
} from 'typeorm';

import { FuelType, VehicleStatus, VehicleType } from '../../common/enums';
import { Attendance } from '../attendance/attendance.entity';
import { FuelLog } from '../fuel/fuel-log.entity';

@Entity({ name: 'vehicles' })
export class Vehicle {
  @PrimaryGeneratedColumn('uuid')
  id!: string;

  // Human-readable asset tag, auto-generated by the service in the format
  // "AST-001" (zero-padded to at least 3 digits). Kept unique so it can be
  // used as an alternate identifier in reports.
  @Column({ type: 'varchar', nullable: true, unique: true })
  assetNumber?: string | null;

  @Column({ unique: true })
  plateNumber!: string;

  @Column({ type: 'varchar', length: 32, default: VehicleType.TRUCK })
  type!: VehicleType;

  @Column({ type: 'varchar', length: 32, default: VehicleStatus.ACTIVE })
  status!: VehicleStatus;

  @Column({ type: 'varchar', length: 16, default: FuelType.DIESEL })
  fuelType!: FuelType;

  @Column({ type: 'float', default: 0 })
  fuelCapacity!: number;

  // Fuel economy in kilometres per litre (KM/L). Optional - defaults to 0
  // until a real reading is recorded.
  @Column({ type: 'float', default: 0 })
  mileage!: number;

  @Column({ type: 'float', default: 0 })
  currentOdometer!: number;

  @Column({ type: 'varchar', nullable: true })
  assignedSite?: string | null;

  @OneToMany(() => FuelLog, (log) => log.vehicle)
  fuelLogs!: FuelLog[];

  @OneToMany(() => Attendance, (att) => att.vehicle)
  attendanceRecords!: Attendance[];

  @CreateDateColumn()
  createdAt!: Date;

  @UpdateDateColumn()
  updatedAt!: Date;
}
